SELECT rating_bucket, city, rating_count FROM (SELECT CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.4 THEN 'mid' ELSE 'low' END AS rating_bucket, city, COUNT(rating) AS rating_count FROM suppliers WHERE rating <= 1.9 GROUP BY CASE WHEN rating >= 4.2 THEN 'high' WHEN rating >= 1.4 THEN 'mid' ELSE 'low' END, city) AS t WHERE rating_count > 5 ORDER BY city, rating_count
